// Owner: S3 · Triage & Agent Orchestration — Karunathilaka K.D.J.C (IT24100551)
// Ownership is binding — do not edit this file if it is not yours. docs/OWNERSHIP.tsv
import { useCallback, useEffect, useState } from 'react'
import { Link } from 'react-router-dom'

import { StatusBadge } from '../../components/shared/StatusBadge'
import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import {
  apiClient,
  type AgentTraceDto,
  type ApprovedGuidanceDto,
  type EpisodeDto,
  type FamilyDashboardDto,
  type FamilyDto,
  type PagedResult,
  type TriageCaseDto,
} from '../../services/apiClient'
import { useAppSelector } from '../../store/hooks'

type Metrics = { first: number; second: number; third: number }

export function DashboardPage() {
  const user = useAppSelector((state) => state.auth.user)
  const isDoctor = user?.role === 'DOCTOR'
  const isAdmin = user?.role === 'ADMIN'
  const isFamilyUser = !isDoctor && !isAdmin

  const [metrics, setMetrics] = useState<Metrics | null>(null)
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [family, setFamily] = useState<FamilyDto | null>(null)
  const [cases, setCases] = useState<TriageCaseDto[]>([])
  const [casesLoading, setCasesLoading] = useState(false)

  // Agent Trace Viewer state
  const [selectedCaseId, setSelectedCaseId] = useState<string | null>(null)
  const [traces, setTraces] = useState<AgentTraceDto[] | null>(null)
  const [tracesLoading, setTracesLoading] = useState(false)
  const [advisory, setAdvisory] = useState<ApprovedGuidanceDto | null>(null)

  // New Complaint Dialog state
  const [showNewComplaint, setShowNewComplaint] = useState(false)
  const [complaintMemberId, setComplaintMemberId] = useState('')
  const [symptomsText, setSymptomsText] = useState('Fever, mild headache, fatigue')
  const [durationDays, setDurationDays] = useState(2)
  const [severity, setSeverity] = useState(4)
  const [notesText, setNotesText] = useState('Patient resting at home.')
  const [submittingComplaint, setSubmittingComplaint] = useState(false)
  const [complaintMessage, setComplaintMessage] = useState('')

  const loadFamilyCases = useCallback(async (familyId: string) => {
    setCasesLoading(true)
    try {
      const { data } = await apiClient.get<PagedResult<TriageCaseDto>>(`/families/${familyId}/triage-cases`, {
        params: { page: 1, pageSize: 20 },
      })
      setCases(data.items)
    } catch {
      // Non-critical if cases fail to load
    } finally {
      setCasesLoading(false)
    }
  }, [])

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      if (isDoctor) {
        const { data } = await apiClient.get<PagedResult<TriageCaseDto>>('/doctors/me/cases', {
          params: { page: 1, pageSize: 100 },
        })
        setMetrics({
          first: data.totalCount,
          second: data.items.filter((item) => item.status === 'PendingDoctorReview').length,
          third: data.items.filter((item) => item.status.startsWith('Approved')).length,
        })
      } else if (isAdmin) {
        const { data } = await apiClient.get<PagedResult<unknown>>('/admin/doctors', {
          params: { page: 1, pageSize: 1 },
        })
        setMetrics({ first: data.totalCount, second: data.totalCount, third: 0 })
      } else {
        const { data: currentFamily } = await apiClient.get<FamilyDto>('/families/me')
        setFamily(currentFamily)
        if (currentFamily.members.length > 0) {
          setComplaintMemberId(currentFamily.members[0].id)
        }
        const { data } = await apiClient.get<FamilyDashboardDto>(`/families/${currentFamily.id}/dashboard`)
        setMetrics({
          first: data.openCases,
          second: data.awaitingDoctorReview,
          third: data.recordsCount,
        })
        await loadFamilyCases(currentFamily.id)
      }
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [isDoctor, isAdmin, loadFamilyCases])

  useEffect(() => {
    void load()
  }, [load])

  // Load Agent Traces for selected case
  const viewTraces = useCallback(async (caseId: string) => {
    setSelectedCaseId(caseId)
    setTraces(null)
    setAdvisory(null)
    setTracesLoading(true)
    try {
      const [tracesRes, guidanceRes] = await Promise.allSettled([
        apiClient.get<AgentTraceDto[]>(`/triage-cases/${caseId}/traces`),
        apiClient.get<ApprovedGuidanceDto>(`/triage-cases/${caseId}/approved-guidance`),
      ])
      if (tracesRes.status === 'fulfilled') {
        setTraces(tracesRes.value.data)
      }
      if (guidanceRes.status === 'fulfilled') {
        setAdvisory(guidanceRes.value.data)
      }
    } catch {
      // Ignored
    } finally {
      setTracesLoading(false)
    }
  }, [])

  // Submit new triage complaint
  const handleSubmitComplaint = async (event: React.FormEvent) => {
    event.preventDefault()
    if (!complaintMemberId) return
    setSubmittingComplaint(true)
    setComplaintMessage('')
    try {
      const symptomsList = symptomsText
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean)
      const { data: episode } = await apiClient.post<EpisodeDto>(`/members/${complaintMemberId}/episodes`, {
        symptoms: symptomsList,
        durationDays,
        severity,
        notes: notesText.trim() || null,
      })
      const { data: triageCase } = await apiClient.post<TriageCaseDto>(`/episodes/${episode.id}/triage`)
      setComplaintMessage('Triage complaint submitted! Multi-agent pipeline is processing in background.')
      if (family) {
        await loadFamilyCases(family.id)
      }
      setShowNewComplaint(false)
      // Automatically open traces viewer for the new case
      void viewTraces(triageCase.id)
    } catch {
      setComplaintMessage('Failed to submit triage complaint. Please check symptoms and member selection.')
    } finally {
      setSubmittingComplaint(false)
    }
  }

  return (
    <div className="page-stack">
      <section className="welcome-banner" aria-label="Workspace overview">
        <div className="welcome-banner-content">
          <p className="eyebrow">Workspace overview</p>
          <h1>Good day, {user?.name}</h1>
          <p>Review current workload, health updates, and access your next permitted task.</p>
        </div>
        <div className="live-status-pill">
          <span className="pulse-dot" aria-hidden="true" />
          <span>{isDoctor ? 'VERIFIED' : 'ACTIVE'}</span>
        </div>
      </section>

      {status === 'loading' ? (
        <div className="skeleton-grid" role="status" aria-label="Loading workspace summary">
          <div className="skeleton-card" />
          <div className="skeleton-card" />
          <div className="skeleton-card" />
        </div>
      ) : status === 'error' ? (
        <ErrorState message="Workspace summary could not be loaded." onRetry={() => void load()} />
      ) : (
        <section className="metric-grid" aria-label="Workspace summary">
          <article className="metric-card metric-card--teal">
            <div className="metric-card-top">
              <span>Open items</span>
              <span className="metric-icon-badge metric-icon-badge--teal" aria-hidden="true">
                📋
              </span>
            </div>
            <strong>{metrics?.first ?? 0}</strong>
            <small>Within your permitted scope</small>
          </article>
          <article className="metric-card metric-card--amber">
            <div className="metric-card-top">
              <span>Awaiting review</span>
              <span className="metric-icon-badge metric-icon-badge--amber" aria-hidden="true">
                ⏳
              </span>
            </div>
            <strong>{metrics?.second ?? 0}</strong>
            <small>Requires authorized action</small>
          </article>
          <article className="metric-card metric-card--blue">
            <div className="metric-card-top">
              <span>{isDoctor ? 'Approved' : 'Records visible'}</span>
              <span className="metric-icon-badge metric-icon-badge--blue" aria-hidden="true">
                🛡️
              </span>
            </div>
            <strong>{metrics?.third ?? 0}</strong>
            <small>Access-controlled data</small>
          </article>
        </section>
      )}

      {/* ===== S3 Feature: Family Triage & Agentic AI Activity ===== */}
      {isFamilyUser && (
        <section className="panel" aria-labelledby="triage-activity-heading">
          <div className="panel-heading">
            <div>
              <p className="eyebrow">Triage &amp; Agent Orchestration (S3)</p>
              <h2 id="triage-activity-heading">Family Triage &amp; Agent Activity</h2>
              <p>
                Multi-agent pipeline (Coordinator &rarr; Context &rarr; Analysis &rarr; Familial Risk &rarr; Safety Gate)
              </p>
            </div>
            <button
              type="button"
              className="button button--primary"
              onClick={() => setShowNewComplaint((prev) => !prev)}
            >
              {showNewComplaint ? 'Cancel Complaint' : '+ New Triage Complaint'}
            </button>
          </div>

          {complaintMessage && (
            <div style={{ padding: '12px 16px', marginBottom: '16px', borderRadius: '8px', background: 'rgba(56, 189, 248, 0.1)', border: '1px solid rgba(56, 189, 248, 0.3)' }}>
              <p style={{ margin: 0, fontSize: '0.9rem' }}>{complaintMessage}</p>
            </div>
          )}

          {/* New Complaint Form */}
          {showNewComplaint && family && (
            <form
              onSubmit={(e) => void handleSubmitComplaint(e)}
              style={{
                marginBottom: '24px',
                padding: '16px',
                borderRadius: '8px',
                background: 'rgba(255, 255, 255, 0.03)',
                border: '1px solid var(--glass-edge-dim)',
              }}
            >
              <h3>Submit Symptoms for Agentic Triage</h3>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '12px', marginBottom: '12px' }}>
                <label className="field">
                  <span>Family Member</span>
                  <select
                    value={complaintMemberId}
                    onChange={(e) => setComplaintMemberId(e.target.value)}
                    required
                  >
                    {family.members.map((m) => (
                      <option key={m.id} value={m.id}>
                        {m.displayName} ({m.role})
                      </option>
                    ))}
                  </select>
                </label>
                <label className="field">
                  <span>Duration (Days)</span>
                  <input
                    type="number"
                    min={1}
                    max={60}
                    value={durationDays}
                    onChange={(e) => setDurationDays(Number(e.target.value))}
                    required
                  />
                </label>
                <label className="field">
                  <span>Severity (1-10)</span>
                  <input
                    type="number"
                    min={1}
                    max={10}
                    value={severity}
                    onChange={(e) => setSeverity(Number(e.target.value))}
                    required
                  />
                </label>
              </div>
              <label className="field" style={{ marginBottom: '12px' }}>
                <span>Symptoms (comma-separated)</span>
                <input
                  type="text"
                  value={symptomsText}
                  onChange={(e) => setSymptomsText(e.target.value)}
                  placeholder="e.g. Fever, persistent headache, cough"
                  required
                />
              </label>
              <label className="field" style={{ marginBottom: '16px' }}>
                <span>Additional Clinical Notes</span>
                <input
                  type="text"
                  value={notesText}
                  onChange={(e) => setNotesText(e.target.value)}
                  placeholder="e.g. Mild chills, no prior medication"
                />
              </label>
              <div style={{ display: 'flex', gap: '10px' }}>
                <button
                  type="submit"
                  className="button button--primary"
                  disabled={submittingComplaint}
                >
                  {submittingComplaint ? 'Starting Multi-Agent Pipeline...' : 'Run Agentic Triage'}
                </button>
                <button
                  type="button"
                  className="button button--secondary"
                  onClick={() => setShowNewComplaint(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          )}

          {/* Cases List */}
          {casesLoading ? (
            <LoadingState label="Loading family triage cases" />
          ) : cases.length === 0 ? (
            <EmptyState
              title="No triage cases yet"
              message="Submit a symptom complaint above or via the mobile app to run the agentic triage pipeline."
            />
          ) : (
            <div className="table-scroll">
              <table>
                <caption className="sr-only">Family triage cases list</caption>
                <thead>
                  <tr>
                    <th>Case ID</th>
                    <th>Created At</th>
                    <th>Priority</th>
                    <th>Triage Status</th>
                    <th>Agentic Action</th>
                  </tr>
                </thead>
                <tbody>
                  {cases.map((c) => (
                    <tr key={c.id}>
                      <td className="data-value" style={{ fontFamily: 'monospace', fontSize: '0.85rem' }}>
                        {c.id.slice(0, 8)}...
                      </td>
                      <td>{new Date(c.createdAt).toLocaleString()}</td>
                      <td>{c.priority}</td>
                      <td>
                        <StatusBadge status={c.status} />
                      </td>
                      <td>
                        <button
                          type="button"
                          className="button button--secondary"
                          style={{ padding: '6px 12px', fontSize: '0.85rem' }}
                          onClick={() => void viewTraces(c.id)}
                        >
                          {selectedCaseId === c.id ? 'Viewing Trace' : 'View Agent Trace'}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* ===== S3 Agent Trace Viewer ===== */}
          {selectedCaseId && (
            <article
              className="panel"
              style={{
                marginTop: '20px',
                background: 'rgba(15, 23, 42, 0.65)',
                border: '1px solid rgba(56, 189, 248, 0.3)',
                borderRadius: '12px',
                padding: '20px',
              }}
            >
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  borderBottom: '1px solid var(--glass-edge-dim)',
                  paddingBottom: '12px',
                  marginBottom: '16px',
                }}
              >
                <div>
                  <p className="eyebrow" style={{ color: 'var(--primary)', marginBottom: '4px' }}>
                    Agentic Transparency Log
                  </p>
                  <h3 style={{ margin: 0 }}>
                    Trace Execution: <span style={{ fontFamily: 'monospace' }}>{selectedCaseId}</span>
                  </h3>
                </div>
                <button
                  type="button"
                  className="button button--secondary"
                  style={{ padding: '4px 10px', fontSize: '0.8rem' }}
                  onClick={() => setSelectedCaseId(null)}
                >
                  Close Trace
                </button>
              </div>

              {tracesLoading ? (
                <LoadingState label="Loading agent trace records from database" />
              ) : !traces || traces.length === 0 ? (
                <p style={{ color: 'var(--faint)' }}>
                  No traces recorded yet for this case. The background orchestrator is initializing...
                </p>
              ) : (
                <>
                  <div className="table-scroll">
                    <table>
                      <thead>
                        <tr>
                          <th>Step</th>
                          <th>Agent Kind</th>
                          <th>Status</th>
                          <th>Tools Allowed</th>
                          <th>Tools Denied</th>
                          <th>Confidence</th>
                          <th>Latency</th>
                        </tr>
                      </thead>
                      <tbody>
                        {traces.map((t) => (
                          <tr key={`${t.stepNumber}-${t.agent}`}>
                            <td><strong>#{t.stepNumber}</strong></td>
                            <td>
                              <span
                                style={{
                                  padding: '2px 8px',
                                  borderRadius: '4px',
                                  background: 'rgba(56, 189, 248, 0.15)',
                                  color: '#38bdf8',
                                  fontWeight: 600,
                                  fontSize: '0.85rem',
                                }}
                              >
                                {t.agent}
                              </span>
                            </td>
                            <td>
                              <StatusBadge status={t.status} />
                            </td>
                            <td style={{ fontSize: '0.85rem', color: '#a7f3d0' }}>
                              {t.toolsAllowed.length > 0 ? t.toolsAllowed.join(', ') : 'None'}
                            </td>
                            <td style={{ fontSize: '0.85rem', color: t.toolsDenied.length > 0 ? '#f87171' : 'var(--faint)' }}>
                              {t.toolsDenied.length > 0 ? t.toolsDenied.join(', ') : 'None (0 violations)'}
                            </td>
                            <td>
                              <span style={{ fontWeight: 600, color: t.confidence >= 0.6 ? '#4ade80' : '#f87171' }}>
                                {(t.confidence * 100).toFixed(0)}%
                              </span>
                            </td>
                            <td style={{ fontSize: '0.85rem' }}>{t.latencyMilliseconds} ms</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>

                  {advisory && (
                    <div
                      style={{
                        marginTop: '16px',
                        padding: '16px',
                        borderRadius: '8px',
                        background: 'rgba(34, 197, 94, 0.1)',
                        border: '1px solid rgba(34, 197, 94, 0.3)',
                      }}
                    >
                      <h4 style={{ margin: '0 0 8px', color: '#4ade80' }}>Doctor Approved Advisory</h4>
                      <p style={{ margin: '0 0 6px', fontWeight: 500 }}>{advisory.finalAdvisory}</p>
                      <small style={{ color: 'var(--faint)', display: 'block' }}>{advisory.disclaimer}</small>
                    </div>
                  )}
                </>
              )}
            </article>
          )}
        </section>
      )}

      {/* Quick Navigation Cards */}
      <section className="panel">
        <div className="panel-heading">
          <div>
            <p className="eyebrow">Next actions</p>
            <h2>Continue your work</h2>
          </div>
        </div>
        <div className="action-grid">
          {isDoctor ? (
            <>
              <Link className="action-card action-card--teal" to="/cases">
                <div className="action-card-header">
                  <strong>Review triage queue</strong>
                  <span className="action-card-arrow" aria-hidden="true">
                    &rarr;
                  </span>
                </div>
                <span>Open verified case grants and structured context.</span>
              </Link>
              <Link className="action-card action-card--blue" to="/approvals">
                <div className="action-card-header">
                  <strong>Complete approvals</strong>
                  <span className="action-card-arrow" aria-hidden="true">
                    &rarr;
                  </span>
                </div>
                <span>Review validated drafts awaiting clinical decision.</span>
              </Link>
            </>
          ) : (
            <>
              <Link className="action-card action-card--teal" to="/records">
                <div className="action-card-header">
                  <strong>Browse records</strong>
                  <span className="action-card-arrow" aria-hidden="true">
                    &rarr;
                  </span>
                </div>
                <span>Search permitted family record summaries.</span>
              </Link>
              {user?.role !== 'MEMBER' && (
                <Link className="action-card action-card--blue" to="/audit">
                  <div className="action-card-header">
                    <strong>Review access history</strong>
                    <span className="action-card-arrow" aria-hidden="true">
                      &rarr;
                    </span>
                  </div>
                  <span>See who accessed permitted information.</span>
                </Link>
              )}
            </>
          )}
        </div>
      </section>
    </div>
  )
}

